mappings.PAY.response:
status = 200
  ? (body.ok = true and $type(body.robiTxn) = "string" and body.robiTxn != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.robiTxn, "code": body.rc}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 400 and $type(body.rc) = "string" and body.rc != ""
  ? {"outcome": "FAILED", "code": body.rc, "message": body.text}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.INQUIRY.response:
status = 200
  ? (body.ok = true and $type(body.invoice) = "string" and $type(body.due) = "string" and $type(body.minPay) = "string"
      ? {"outcome": "SUCCESS", "partnerRef": body.invoice, "code": body.rc, "attributes": {"outstanding": body.due, "minimum": body.minPay}}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 400 and $type(body.rc) = "string" and body.rc != ""
  ? {"outcome": "FAILED", "code": body.rc, "message": body.text}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.STATUS_QUERY.response:
status = 200
  ? (body.ok = true and $type(body.robiTxn) = "string" and body.robiTxn != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.robiTxn, "code": body.rc}
      : body.ok = false and $type(body.rc) = "string" and body.rc != ""
        ? {"outcome": "FAILED", "code": body.rc, "message": body.text}
        : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.ok = false
  ? {"outcome": "NOT_FOUND", "code": body.rc, "message": body.text}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.REVERSE.response:
status = 200
  ? (body.ok = true and $type(body.robiTxn) = "string" and body.robiTxn != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.robiTxn, "code": body.rc}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 400 or status = 404) and $type(body.rc) = "string" and body.rc != ""
  ? {"outcome": "FAILED", "code": body.rc, "message": body.text}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}
